"pkglib.fpkgsupport.lead": "یک بسته‌ی جعلی PS5 تنها وقتی نصب می‌شود که پشتیبانی بسته‌ی جعلی از قبل روی کنسول بارگذاری شده باشد. قبل از نصب، هر سه را به این ترتیب بارگذاری کنید:",
