about_disclaimer_title: "سلب مسئولیت",
about_disclaimer_purpose:
  "ps5upload تنها برای مقاصد تحقیقاتی، آموزشی، همکاری‌پذیری و توسعه‌ی homebrew ارائه می‌شود. با Sony Interactive Entertainment Inc. وابسته، تأییدشده یا مرتبط نیست. «PlayStation» و «PS5» علائم تجاری Sony Interactive Entertainment Inc. هستند و تنها برای شناسایی استفاده می‌شوند.",
about_disclaimer_risk:
  "این نرم‌افزار «همان‌طور که هست» ارائه می‌شود، بدون هرگونه ضمانت. کار با یک کنسول تغییر‌یافته می‌تواند به‌طور دائم به آن آسیب بزند، ذخیره‌ها و مجوزها را به‌طور بازگشت‌ناپذیر از بین ببرد و حساب یا کنسول شما را ممنوع کند. استفاده کاملاً به عهده‌ی خود شماست و مسئولیت کامل عواقب را می‌پذیرید. قبل از شروع از هر چیزی که نمی‌توانید از دست دادنش را تحمل کنید پشتیبان بگیرید.",
about_disclaimer_piracy:
  "تنها با سخت‌افزاری که مالک آن هستید و محتوایی که قانوناً مالک آن هستید استفاده کنید. نباید برای کپی، توزیع یا اجرای نرم‌افزاری که حق استفاده از آن را ندارید به‌کار رود.",
