upload_mount_readonly_desc: "توصیه‌شده. جلوگیری می‌کند از نوشتن داده‌ی ذخیره توسط PS5 در تصویر (که بی‌صدا فایل روی دیسک را خراب و اتصال دوباره را می‌شکند). وقتی قصد ویرایش تصویر را دارید خاموش کنید — جایگزینی فایل‌ها، افزودن DLC یا اعمال پچ backport — و به یاد داشته باشید این ویرایش‌ها دائمی هستند.",
