"arcpkg.choose": "انتخاب آرشیو…",
"arcpkg.help": "برای فایل ‎.zip، ‎.7z یا ‎.rar که یک یا چند فایل ‎.pkg در هر پوشه‌ای درون خود دارد. فقط بسته‌ها باز می‌شوند، مستقیم روی PS5 (چیزی روی این رایانه استخراج نمی‌شود) و سپس یکی‌یکی نصب می‌شوند: اول بازی اصلی، بعد به‌روزرسانی آن، بعد DLC. آرشیو RAR چندبخشی (‎.part1.rar، ‎.part2.rar…) پشتیبانی می‌شود: بخش اول را انتخاب کنید و بقیه را کنار آن نگه دارید. اگر RAR رمز بخواهد پرسیده می‌شود؛ ZIP و 7z رمزدار پشتیبانی نمی‌شوند.",
"arcpkg.keepsRunning": "اگر صفحهٔ دیگری را باز کنید این کار ادامه پیدا می‌کند و در «کارها» هم دیده می‌شود.",
"arcpkg.notArchive": "این فایل آرشیو ‎.zip، ‎.7z یا ‎.rar نیست.",
"arcpkg.pick": "یک آرشیو انتخاب کنید",
"arcpkg.title": "نصب بسته‌ها از آرشیو",
"install.library.title": "نسخه‌های بسته روی PS5",
"install.stream.file.help": "یک فایل ‎.pkg یا ‎.fpkg انتخاب کنید یا آن را هر جای این پنجره رها کنید. تا پایان نصب برنامه را باز نگه دارید؛ پیشرفت در صف بالا و در «کارها» دیده می‌شود.",
"install.stream.file.title": "نصب یک فایل بسته",
"install.tab.stream.lead": "PS5 مستقیم از این رایانه یا از یک پیوند نصب می‌کند. ابتدا نسخه‌ای روی PS5 قرار نمی‌گیرد، پس آنجا فضای خالی لازم نیست و این مطمئن‌ترین روش نصب است.",
"install.tab.upload.lead": "بسته ابتدا روی PS5 کپی می‌شود و سپس از همان نسخه نصب می‌شود. وقتی از این روش استفاده کنید که PS5 به این رایانه دسترسی ندارد (استریم با خطای شبکه شکست می‌خورد)، یا می‌خواهید بسته‌ها روی PS5 بمانند تا بعداً بدون این رایانه دوباره نصب شوند.",
"install.upload.file.browser": "کپی بسته روی PS5 از اینجا به برنامهٔ دسکتاپ نیاز دارد. در رابط وب از «استریم و نصب» استفاده کنید، یا در پایین بسته‌هایی را نصب کنید که از قبل روی PS5 هستند.",
"install.upload.file.help": "یک فایل ‎.pkg یا ‎.fpkg انتخاب کنید. این نسخه به اندازهٔ کل بسته فضای خالی روی PS5 نیاز دارد و تا وقتی حذفش نکنید در فهرست پایین می‌ماند.",
"install.upload.file.title": "کپی بسته روی PS5 و نصب آن",
"linkcard.confirm.direct": "PS5 خودش بسته را از پیوند دانلود و نصب می‌کند. پس از شروع دیگر به این رایانه نیازی نیست و پیشرفت روی PS5 (دانلودها) دیده می‌شود، نه اینجا. اگر PS5 نتواند به پیوند برسد، برنامه آن را از طریق این رایانه منتقل می‌کند. نصب دوباره روی بازی نصب‌شده، در صورت شکست نصب‌کنندهٔ Sony، ممکن است آن بازی را حذف کند. فقط از پیوند بسته‌هایی استفاده کنید که به آن‌ها اعتماد دارید و حق نصبشان را دارید.",
"linkcard.confirm.download": "این رایانه ابتدا کل بسته را روی دیسک ذخیره می‌کند و سپس آن را روی PS5 نصب می‌کند. تا پایان هر دو مرحله باید روشن بماند و برای بسته فضای خالی لازم دارد. نصب دوباره روی بازی نصب‌شده، در صورت شکست نصب‌کنندهٔ Sony، ممکن است آن بازی را حذف کند. فقط از پیوند بسته‌هایی استفاده کنید که به آن‌ها اعتماد دارید و حق نصبشان را دارید.",
"linkcard.confirm.stream": "این رایانه بسته را دانلود می‌کند و بی‌درنگ به PS5 می‌دهد، پس تا پایان نصب باید روشن و متصل بماند. چیزی روی دیسک ذخیره نمی‌شود. نصب دوباره روی بازی نصب‌شده، در صورت شکست نصب‌کنندهٔ Sony، ممکن است آن بازی را حذف کند. فقط از پیوند بسته‌هایی استفاده کنید که به آن‌ها اعتماد دارید و حق نصبشان را دارید.",
