health_junk_explain_v2: "چیزهایی که ps5upload ساخته و دیگر لازم نیستند: فایل‌های ناتمام از انتقال‌های قطع‌شده، نسخه‌های بسته که بیش از یک ساعت در پوشهٔ موقت مانده‌اند، و فایل‌های قدیمی تست سرعت. فقط پوشه‌های خود ps5upload بررسی می‌شوند؛ به بازی‌ها، بسته‌ها و ذخیره‌های شما هرگز دست زده نمی‌شود.",
