"speedtest.verdict.gigabit": "این یک اتصال گیگابیتی کامل است: بیشترین سرعتی که درگاه شبکهٔ PS5 می‌تواند داشته باشد.",
"speedtest.verdict.hundred": "به نظر می‌رسد این اتصال ۱۰۰ مگابیتی است که سقف آن حدود ۱۱ مگابایت بر ثانیه است. کابل (Cat5e یا بهتر) را بررسی کنید و مطمئن شوید همهٔ درگاه‌های سوئیچ یا روتر در مسیر گیگابیتی‌اند.",
"speedtest.verdict.mid": "قابل استفاده است، اما کمتر از توان کابل گیگابیتی (۹۰ تا ۱۱۵ مگابایت بر ثانیه). علت معمول، Wi-Fi در یکی از دو طرف یا ترافیک دیگر روی شبکه است.",
"speedtest.verdict.slow": "کند است. معمولاً علت آن سیگنال ضعیف Wi-Fi، VPN یا شبکهٔ شلوغ است. راه‌حل، کابل شبکه به PS5 است.",
stop: "توقف",
activity_description_v2: "هر کاری که برنامه روی کنسول‌های شما انجام می‌دهد و انجام داده است: بارگذاری‌ها، دانلودها، نصب‌ها و عملیات فایل. هر کدام را از اینجا متوقف یا دوباره امتحان کنید. ۱۰۰ مورد اخیر، حتی پس از راه‌اندازی دوباره، نگه داشته می‌شود.",
disk_usage_description_v2: "ببینید چه چیزی فضای PS5 را اشغال کرده است. هر بلوک یک پوشه است که اندازه‌اش متناسب با محتوای آن است؛ برای دیدن درون بلوک روی آن کلیک کنید.",
fw_spoof_subtitle_v2: "بررسی می‌کند که آیا نسخهٔ فرم‌ور گزارش‌شده توسط این PS5 با یک پی‌لود جعل نسخه تغییر کرده است، تا پیش از نصب چیزی که به آن وابسته است نسخهٔ واقعی را بدانید.",
health_subtitle_v2: "بررسی می‌کند که PS5، این برنامه و شبکهٔ میان آن‌ها کار می‌کنند، اگر کار نکنند می‌گوید چه چیزی را درست کنید، و سرعت انتقال فایل میان آن‌ها را اندازه می‌گیرد.",
localimage_subtitle_v2: "یک ایمیج بازی (‎.exfat یا ‎.ffpkg) را که روی این رایانه است باز کنید و بدون باز کردن کل آن، فایل‌های درونش را اضافه، جایگزین یا حذف کنید.",
processes_subtitle_v2: "برنامه‌هایی که همین حالا روی PS5 در حال اجرا هستند. هر کدام را متوقف یا دوباره راه‌اندازی کنید؛ مراقب پردازه‌های سیستمی باشید: متوقف‌کردن پردازهٔ اشتباه ممکن است کنسول را قفل کند.",
remotePlay_subtitle_v2: "این PS5 را برای Remote Play آماده کنید و PIN‌ای بگیرید که برنامهٔ PS Remote Play را به آن پیوند می‌دهد.",
saves_description_v2: "داده‌های ذخیره روی PS5، یک ورودی برای هر بازی. از ذخیره‌های یک بازی در قالب ‎.zip روی این رایانه پشتیبان بگیرید و بعداً بازیابی کنید.",
shell_description_v2: "فرمان‌هایی تایپ کنید که روی PS5 و درون پردازهٔ کمک‌کار اجرا می‌شوند. برای کاربران پیشرفته. خروجی هر فرمان به ۲۵۶ کیلوبایت محدود است؛ کلیدهای بالا و پایین فرمان‌های قبلی را برمی‌گردانند.",
