"convert_games.subtitle": "یک پوشه یا ایمیج بازی را به بستهٔ قابل نصب (‎.pkg) تبدیل کنید، یا یک پوشهٔ بازی را به ایمیج بازی (‎.exfat یا ‎.ffpfsc کوچک‌تر) که ShadowMount+ آن را مانت می‌کند. کار روی این رایانه انجام می‌شود، نه روی کنسول.",
