"engine_problem.remote.fix": "بررسی کنید موتور (کانتینر Docker یا رایانهٔ دیگر) در حال اجراست و از آن نشانی در دسترس است، یا نشانی را در «تنظیمات» تغییر دهید.",
"engine_problem.remote.why": "موتوری که این برنامه برای استفاده تنظیم شده ({url}) پاسخ نمی‌دهد.",
"engine_problem.restart": "راه‌اندازی دوبارهٔ موتور",
"engine_problem.slow.fix": "«راه‌اندازی دوبارهٔ موتور» را بزنید. دیوار آتش یا آنتی‌ویروسی که اتصال‌های محلی را فیلتر می‌کند هم می‌تواند علت باشد: به ps5upload-engine اجازه دهید.",
"engine_problem.slow.why": "موتور در حال اجراست اما پاسخ نمی‌دهد.",
"engine_problem.stopped.fix": "«راه‌اندازی دوبارهٔ موتور» را بزنید. اگر دوباره متوقف شد، صفحهٔ «گزارش‌ها» علت را نشان می‌دهد.",
"engine_problem.stopped.why": "موتور اجرا نمی‌شود: متوقف شده یا هرگز شروع نشده است.",
"engine_problem.title": "برنامه نمی‌تواند به موتورش روی این رایانه برسد",
"engine_problem.web.fix": "بررسی کنید سرور (کانتینر Docker) در حال اجراست، سپس این صفحه را دوباره بارگذاری کنید.",
"engine_problem.web.why": "این صفحه اتصالش را با سرور ps5upload که از آن آمده از دست داد.",
gate_engine_down_body_v2: "این صفحه به موتور برنامه نیاز دارد که پاسخ نمی‌دهد. اعلان بالای پنجره علت را می‌گوید و می‌تواند آن را دوباره راه بیندازد.",
"profile.description_v2": "تصویر پروفایل کنسول و نام کاربری حساب آفلاین را تغییر دهید، و یک حساب را به‌صورت آفلاین وارد PlayStation Network کنید.",
"profile.np.body": "باعث می‌شود PS5 حساب واردشده را وارد PlayStation Network بداند، بدون تماس با Sony. برخی امکانات کنسول فقط برای حساب واردشده باز می‌شوند، از جمله Remote Play. از np-fake-signin ساختهٔ earthonion استفاده می‌کند که با زدن دکمه از صفحهٔ پروژه گرفته می‌شود.",
"profile.np.confirm_body": "np-fake-signin فایل‌ها و تنظیمات ورود PlayStation Network را برای {user} روی PS5 می‌نویسد. چیزی به Sony فرستاده نمی‌شود. پس از آن PS5 را دوباره راه بیندازید. برای بازگرداندن: تنظیمات > کاربران و حساب‌ها > سایر > خروج از حساب.",
"profile.np.confirm_title": "این حساب وارد شود؟",
"profile.np.failed": "ورود اجرا نشد",
"profile.np.fetching": "در حال گرفتن np-fake-signin…",
"profile.np.sending": "در حال ارسال به PS5…",
"profile.np.sent": "np-fake-signin {version} روی PS5 اجرا شد. برای پایان، PS5 را دوباره راه بیندازید؛ آنگاه حساب واردشده نشان داده می‌شود و می‌توان تنظیمات > سیستم > Remote Play را روشن کرد.",
"profile.np.sign_in": "ورود",
"profile.np.state_loading": "در حال خواندن حساب…",
"profile.np.state_no_slot": "هیچ حسابی در بالا با نام {user} نیست، پس np-fake-signin متوقف می‌شود. نام حساب را همان نام کاربر واردشده بگذارید، یا حسابی برای او فعال کنید.",
"profile.np.state_no_user": "هیچ کاربری روی PS5 وارد نشده است. وارد پروفایل دلخواه شوید و برگردید.",
"profile.np.state_not_activated": "{user} (حساب {slot}) هنوز شناسهٔ حساب ندارد. ابتدا آن را در بخش «حساب‌ها» در بالا فعال کنید.",
"profile.np.state_ready": "آماده: {user} (حساب {slot}) فعال است.",
"profile.np.step_activate": "حساب به شناسهٔ حساب نیاز دارد. حساب متصل به PSN آن را دارد؛ در غیر این صورت آن را در بخش «حساب‌ها» در بالا فعال کنید (فعال‌سازی آفلاین).",
"profile.np.step_restart": "PS5 را دوباره راه بیندازید. برای بازگرداندن در آینده: تنظیمات > کاربران و حساب‌ها > سایر > خروج از حساب.",
"profile.np.step_run": "در حالی که آن کاربر روی PS5 وارد است «ورود» را بزنید. یک بار اجرا می‌شود و بسته می‌شود.",
