a11y_dyslexia_hint_v2: "اگر Atkinson Hyperlegible یا OpenDyslexic روی این دستگاه نصب باشد از آن استفاده می‌کند (هیچ‌کدام همراه برنامه نیستند) و فاصله‌ی حروف و خطوط را کمی بیشتر می‌کند. بدون آن‌ها فقط فاصله‌ها تغییر می‌کند.",
a11y_motion_hint_v2: "«خودکار» از تنظیم سیستم‌عامل پیروی می‌کند. «کاهش‌یافته» انیمیشن تغییر صفحه را خاموش و انیمیشن پنجره‌های بازشو را کوتاه می‌کند؛ «هیچ» همه‌ی انیمیشن‌ها و جلوه‌های انتقال را خاموش می‌کند.",
