first_run_step4_body_v2: "یک فلش USB حاوی ایمیج‌های بازی .ffpkg را به PS5 وصل کنید تا ShadowMount+ آن‌ها را خودکار متصل کند — در بازی‌ها ظاهر می‌شوند. برای بارگذاری فایل‌های دیگر یا نصب بسته‌های .pkg، از بارگذاری و نصب بسته استفاده کنید.",
fw_spoof_title_v2: "بررسی جعل فرم‌ور",
game_activity_no_console_playtime: "بدون زمان بازی کنسول",
game_activity_subtitle_v3: "چه چیزی روی این PS5 بازی شده و چه مدت. زمان بازی ردیابی‌شده را راهنمای ps5upload روی کنسول می‌شمارد؛ زمان بازی کنسول از سوابق خود کنسول خوانده می‌شود.",
hardware_description_v2: "اطلاعات سیستم، مدت روشن بودن و حافظه هنگام اتصال راهنما هر ۵ ثانیه خودکار به‌روز می‌شوند. دمای لحظه‌ای و فرکانس CPU در صورت درخواست خوانده می‌شوند — روی «خواندن سنسورها» کلیک کنید. فرم‌ور خرده‌فروشی همه‌ی مقادیر را در اختیار نمی‌گذارد (مثلاً مصرف CPU)؛ آن‌ها با خط تیره نمایش داده می‌شوند.",
