installed_section_disc_hint_v2: "بازی‌های ثبت‌شده‌ای که از ایمیج دیسک اجرا می‌شوند. فقط زمانی متصل و اجرا می‌شوند که ShadowMount+ در حال اجرا باشد. خود فایل‌های ایمیج در «فایل‌های بازی» هستند.",
installed_section_disc_v2: "بازی‌ها از ایمیج‌های دیسک",
keep_ps5_awake_mode_hint_v2: "تایمر آماده‌به‌کار خودکار PS5 را به‌طور دوره‌ای بازنشانی می‌کند تا به حالت استراحت نرود. «هنگام بارگذاری و نصب» از بارگذاری‌های طولانی محافظت می‌کند (دلیل رایج شکست بارگذاری‌ها؛ پیش‌فرض). «همیشه هنگام اتصال» تا وقتی برنامه باز است هر کنسولی را که راهنما رویش اجرا می‌شود از حالت استراحت دور نگه می‌دارد. بردن دستی PS5 به حالت استراحت در همه‌ی حالت‌ها کار می‌کند.",
kernellog_categories_explainer: "همه‌ی دسته‌ها در ابتدا نمایش داده می‌شوند. دسته‌های Sony زیرسیستم‌های خود کنسول هستند که روی هر PS5 جیلبریک‌شده، هر payload‌ای که اجرا شود، مدام گزارش می‌نویسند؛ ربطی به ps5upload ندارند. تیکشان را بردارید تا شلوغی کم شود.",
