processes_kill_payload_title: "payload «{name}» متوقف شود؟",
"profile.np.browser_v2": "ورود به حساب به برنامه‌ی دسکتاپ نیاز دارد: np-fake-signin را دریافت و به PS5 ارسال می‌کند، کاری که رابط وب نمی‌تواند انجام دهد.",
ps5notif_description_v3: "پیام‌هایی که ps5upload روی تلویزیون شما نشان داده (Remote Play، تقلب‌ها)، که از راهنمای آن روی کنسول خوانده می‌شوند. این پنل اعلان‌های خود PS5 نیست. هر ۵ ثانیه به‌روز می‌شود.",
ps5notif_empty_hint_v2: "وقتی ps5upload پیامی روی تلویزیون شما نشان می‌دهد، مثل PIN Remote Play یا روشن شدن یک تقلب، اینجا فهرست می‌شود تا بتوانید دوباره بخوانیدش. این پنل اعلان‌های خود PS5 نیست؛ کنسول اجازه‌ی خواندن آن را به ما نمی‌دهد.",
