remotePlay_open_profile: "باز کردن پروفایل",
reset_confirm_body_browser: "این کار همه‌ی تنظیمات و وضعیت ذخیره‌شده‌ای را که این مرورگر برای PS5Upload نگه می‌دارد پاک می‌کند و صفحه از نو بارگذاری می‌شود. داده‌های خود موتور روی سرور (جفت‌سازی کنسول‌ها، مجموعه، سرورهای ذخیره‌شده، کتابخانه‌های backport، تاریخچه‌ی نصب، گزارش‌ها) دست نمی‌خورند و هیچ چیزی روی PS5 شما هم. این کار قابل بازگشت نیست.",
reset_confirm_body_v2: "این کار همه‌ی داده‌های محلی PS5Upload را برای همیشه حذف می‌کند: تنظیمات، PS5های ذخیره‌شده و جفت‌سازی‌هایشان، مجموعه، سرورهای ذخیره‌شده و رمزهایشان، کتابخانه‌های backport، تاریخچه‌ی نصب، کارها و رویدادها، تاریخچه‌ی فعالیت/صف، گزارش‌ها، حافظه‌ی پنهان payloadها و گزارش‌های خرابی. به هیچ چیزی روی PS5 شما دست نمی‌زند. برنامه در وضعیت تازه بارگذاری می‌شود. این کار قابل بازگشت نیست.",
reset_hint_browser: "همه‌ی تنظیمات و وضعیت ذخیره‌شده‌ای را که این مرورگر برای PS5Upload نگه می‌دارد پاک کنید و از نو شروع کنید. آنچه موتور روی سرورش نگه می‌دارد (جفت‌سازی کنسول‌ها، مجموعه، سرورهای ذخیره‌شده، کتابخانه‌های backport، تاریخچه‌ی نصب، گزارش‌ها) دست نمی‌خورد و هیچ چیزی روی PS5 شما تحت تأثیر قرار نمی‌گیرد.",
reset_hint_v2: "همه‌ی ردهای محلی PS5Upload را پاک کنید و از نو شروع کنید: تنظیمات، PS5های ذخیره‌شده و جفت‌سازی‌هایشان، مجموعه، سرورهای ذخیره‌شده و رمزهایشان، کتابخانه‌های backport، تاریخچه‌ی نصب، کارها و رویدادها، تاریخچه‌ی فعالیت/صف، گزارش‌ها، حافظه‌ی پنهان payloadها و گزارش‌های خرابی. هیچ چیزی روی PS5 شما تحت تأثیر قرار نمی‌گیرد. پشتیبان‌گیری / بازیابی بالا شامل جفت‌سازی‌ها، مجموعه، رمزهای سرور یا کتابخانه‌های backport نمی‌شود.",
saves_backup_usb_tooltip_v2: "این ذخیره را در مسیر ذخیره‌ای که در تنظیمات تعیین شده (یک درایو USB روی PS5) به‌صورت zip روی درایو قرار بده. به این کامپیوتر کپی، فشرده و برگردانده می‌شود، پس برنامه را باز نگه دارید؛ نسخه‌ی اینجا پس از آن حذف می‌شود.",
saves_description_browser: "داده‌ی ذخیره روی PS5، یک ورودی برای هر بازی. پشتیبان‌گیری از ذخیره‌ها در .zip و بازیابی آن‌ها به برنامه‌ی دسکتاپ نیاز دارد؛ اینجا می‌توانید آن‌ها را ببینید و پوشه‌هایشان را باز کنید.",
